// 验收总入口。返回 {pass, failed, needs_inspector, incident}：
//   pass=true  全过，里程碑已推到 done；
//   pass=false 有败，failed[] 逐条点名败因，里程碑已推到 failed（计数/三振由状态机管）；
//   pass=null  程序判的全过但还有人判条目没回填，不定案、不动状态，needs_inspector[] 列出待检条目。
export async function runAcceptance(root, milestoneId, { actor = '脚本' } = {}) {
  const milestones = await readJson(root, MILESTONES_REL);
  if (!Array.isArray(milestones)) {
    throw new Error(`还没有里程碑清单（${MILESTONES_REL}），没法验收`);
  }
  const entry = milestones.find((m) => m.id === milestoneId);
  if (!entry) {
    throw new Error(`里程碑清单里找不到「${milestoneId}」，没法验收`);
  }
