    throw new Error(`里程碑「${milestoneId}」已经是「${status}」，终态不再验收`);
  }
  // 验收只发生在「团队自称完成」与「老板验收」之间：没申报就没得验。
  if (!Number.isInteger(entry.claimed_at_tick)) {
    throw new Error(`里程碑「${milestoneId}」还没申报完成（缺 claimed_at_tick），先经 write milestone-claim 申报再验收`);
  }

  // —— 评判段：纯读，一个字都不写。——
  const failed = [];
  const checked = [];
  const needsInspector = [];
  for (const [i, criterion] of entry.criteria.entries()) {
    const where = `里程碑 ${milestoneId} 第 ${i + 1} 条验收标准`;
    if (criterion.manual === true) {
      needsInspector.push({ index: i, desc: criterion.desc });
      continue;
    }
    const { ok, reason } = await judgeCheck(root, criterion.check, where);
    checked.push({ index: i, desc: criterion.desc, ok, ...(ok ? {} : { reason }) });
    if (!ok) failed.push({ index: i, desc: criterion.desc, reason });
  }

  // 程序判的全过、但有人判条目没回填：不定案。检察会话回填 verdict 之前，状态原地不动。
  if (failed.length === 0 && needsInspector.length > 0) {
    return { pass: null, failed: [], needs_inspector: needsInspector, incident: false };
  }

