          type: 'artifact-review',
          kind: 'artifact-review',
          title: `请老板试用并评审产出：${typeof artifact.title === 'string' ? artifact.title : milestoneId}`,
          artifactId: artifact.id,
          milestone: milestoneId,
          requestedBy: actor,
          tick: entry.claimed_at_tick
        });
        approvalId = filed.id;
        artifactId = artifact.id;
      } else {
        // 已挂单、老板还没拍板：原地继续等（幂等，绝不重复挂单）。
        approvalId = review.id;
        artifactId = review.artifact_id;
      }
      return {
        pass: null,
        failed: [],
        needs_inspector: [],
        awaiting_review: { approval: approvalId, artifact_id: artifactId, milestone: milestoneId },
        incident: false
      };
    }
