  const fresh = await readJson(root, MILESTONES_REL); // advance 刚改过清单，重读再改，不拿旧底稿覆盖
  const freshEntry = fresh.find((m) => m.id === milestoneId);
  if (!freshEntry) {
    throw new Error(`里程碑「${milestoneId}」在写结论前从清单里消失了，账目异常，停手等人查`);
  }
  if (!Array.isArray(freshEntry.verdicts)) freshEntry.verdicts = [];
  freshEntry.verdicts.push(verdict);
  delete freshEntry.claimed_at_tick;
  // 复审义务只管这一轮：过了就销标（下次要复审得由新的报问题重新置）。不过不销——还欠一次复审。
  if (pass) delete freshEntry.review_after_fix;
  await writeJson(root, MILESTONES_REL, fresh, {
    actor,
    event: `验收结论:${milestoneId}:${pass ? '过' : '不过'}`
  });

  // 状态流转由脚本读结论触发：过 → done；不过 → failed（失败计数与三振熔断在状态机里）。
  const result = await advance(root, 'milestone', milestoneId, pass ? 'done' : 'failed', { actor });

  // 放行用掉的那张准入单盖消费戳：之后它顶不了下一轮的门（老板报问题重开、修完要复审时，
  // 旧准入单不许把新一轮悄悄放行）。必须在 advance 之后——之前盖会让硬闸查不到未消费的单、
  // 把这次正当的收官自己拦下。
  if (pass && approvedReviewId !== null) {
    await markReviewConsumed(root, approvedReviewId, entry.claimed_at_tick);
  }

  return { pass, failed, needs_inspector: [], incident: result.incident };
}

