const generation = got.generation;
const seq = got.tickSeq;

// 序号跟进状态档（与 tick-begin 一致）。
const state = await readJson(root, PATHS.state);
if (state === null) {
  throw new Error(`找不到 ${PATHS.state}，项目状态档缺失，脚本验收轮没法开工`);
}
state.tick_seq = seq;
await writeJson(root, PATHS.state, state, {
  actor: '脚本',
  event: `tick-begin:第 ${seq} 轮（第 ${generation} 代，脚本验收轮）`
});

// 登记派工：本轮由 fire 自身跑完，员工记「脚本」、会话用 fire 自身标识（记账归属齐全）。
// 不带 model——脚本验收轮没有任何模型调用，没有用量可归。
const dispatch = { session_id: session, employee: '脚本', tick: seq };
WRITE_TYPES['dispatch'].validate(dispatch);
await appendLine(root, WRITE_TYPES['dispatch'].path(), dispatch);

// ② acceptance-run：评判 + 结论入册 + 状态流转闭环。
const result = await runAcceptance(root, milestone, { actor: '脚本' });

// 评审门：机器标准全过、已挂/认一张评审单等老板准入/打回。本轮活干完（挂单了），结局报
// awaiting-approval——带外调度器据此暂停 loop 等老板，绝不再拉任何会话。必须先于下面的
// pass===null 分支：那条是 AI 检察员（needs_inspector）的专用抛错，评审门与它彻底分家。
if (result.awaiting_review) {
  const ar = result.awaiting_review;
  const narrative = `脚本验收：里程碑「${milestone}」机器标准逐条判定全过，已挂评审单「${ar.approval}」等老板试用产出后准入/打回，全程零模型开销`;
  const nextPlan = `等老板对产出「${ar.artifact_id}」准入或打回：准入则里程碑收官，打回则下一轮直奔老板意见返修`;
  const draftRel = WRITE_TYPES['tick-field'].path(seq);
  const fields = { narrative, next_plan: nextPlan };
  WRITE_TYPES['tick-field'].validate(fields);
  const existing = (await readJson(root, draftRel)) ?? {};
  await writeJson(root, draftRel, { ...existing, ...fields }, { actor: '脚本', event: 'write:tick-field（脚本验收轮·评审门挂单）' });
  const ended = await tickEnd(root, { generation, status: 'awaiting-approval', action: 'acceptance' });
  return {
    output: {
      ok: true,
      fired: false,
      machine_only: true,
      action: 'acceptance',
      milestone,
      awaiting_review: ar,
      tick: ended.seq,
      report: ended.reportRel,
      tick_exit: ended.exit
    },
    exit: ended.exit
  };
}

if (result.pass === null) {
  // 不该发生：预检已判 machine_only（无人判条目）。真出现待人判条目＝清单在预检与此刻之间被
  // 体外改动，喊停不猜（叙述都还没落、锁留原地）。
  throw new Error(
    `里程碑「${milestone}」验收冒出待人判条目，与预检的 machine_only 判定矛盾，` +
    '验收清单可能在预检之后被体外改动，停手等人查'
  );
}

// ③ 固定模板自动叙述 + 下轮计划落草稿（走 tick-field 同一套校验，坏字段进不了草稿）。
const narrative = `脚本验收：里程碑「${milestone}」逐条机器判定，结论「${result.pass ? '通过' : '不通过'}」，全程零模型开销`;
const nextPlan = result.pass
  ? `里程碑「${milestone}」已收官，下一轮按预检行动计划挑下一个里程碑`
  : `里程碑「${milestone}」验收未过，下一轮先落复盘记录再重拆修复 sprint`;
const draftRel = WRITE_TYPES['tick-field'].path(seq);
const fields = { narrative, next_plan: nextPlan };
WRITE_TYPES['tick-field'].validate(fields);
const existing = (await readJson(root, draftRel)) ?? {};
await writeJson(root, draftRel, { ...existing, ...fields }, { actor: '脚本', event: 'write:tick-field（脚本验收轮）' });

// ④ tick-end：结局按验收结果映射——熔断（连败三振）报 incident，其余（过或未过但没熔断）
//    都是「本轮活干完了」报 done-work。退出码由 tick-end 现映射，原样透传。
const status = result.incident ? 'incident' : 'done-work';
const ended = await tickEnd(root, { generation, status, action: 'acceptance' });
return {
